faqs = [
 ("반응속도 빨라지는법이 있나요?", "짧게 자주 연습하고, 신호가 나오기 전에 추측해서 누르지 않는 것이 기본입니다. 충분한 수면, 집중이 유지되는 5~10분 블록, 같은 기기와 화면 조건이 기록을 더 일정하게 만듭니다. 단순 반응속도의 향상 폭은 대체로 크지 않으니 정확도와 실수 횟수도 함께 보세요."),
 ("반응속도 평균은 몇 ms인가요?", "단순 시각 반응시간 연구에서 건강한 성인은 대략 200~250ms 범위로 보고됩니다(Kosinski, 2008; Woods et al., 2015). 브라우저 기록에는 모니터 주사율, 입력 장치와 브라우저 지연이 더해져 보통 조금 더 높게 나옵니다. 한 번의 점수는 의학적 기준이 아니라 개인 기준 기록으로 보세요."),
 ("반응속도 훈련 게임은 무엇부터 하면 좋나요?", "먼저 반응속도 테스트로 기준 기록을 재세요. 반복 자극은 순발력 테스트 게임이나 반응속도 게임, 움직이는 대상은 동체시력 테스트 게임, 빠른 시선 이동은 사케드 갤러리가 맞습니다. 시간 감각 게임은 목표 시간을 맞추는 타이밍 연습이며 반응속도 측정이 아닙니다."),
 ("반사신경 테스트와 반응속도 테스트는 다른가요?", "반응속도 테스트는 하나의 신호에 하나의 동작으로 답하는 단순 반응을 잽니다. 반사신경 훈련 게임은 여러 표적, 방해 자극, 선택이나 방향 변화를 더해 주의력과 시각 판단까지 함께 씁니다. 엄밀한 의학 용어의 반사 신경 검사는 아니며 진단 도구도 아닙니다."),
 ("발로란트나 롤 같은 게임에도 도움이 되나요?", "시각 반응, 표적 포착, 움직이는 대상 추적처럼 게임에 나오는 화면 과제를 따로 연습할 수 있습니다. 하지만 실제 실력에는 맵 이해, 위치 선정, 조준과 팀 판단이 함께 작용합니다. 전이 정도는 게임과 장비, 개인에 따라 다르며 티어 상승을 보장하지 않습니다."),
]
block = '  ko: [\n' + ',\n'.join('    [%s, %s]' % (json.dumps(q, ensure_ascii=False), json.dumps(a2, ensure_ascii=False)) for q, a2 in faqs) + '\n'
